}
function nameRules(n) {
  if (n === "Date") return ["no-clock", "pure"];
  if (["fetch", "WebSocket", "XMLHttpRequest"].includes(n)) return ["no-network", "pure"];
  if (n === "process" || n === "console") return ["no-process", "pure"];
